seq_txt = open("region.fasta").read()
seq = "".join(l.strip() for l in seq_txt.split("\n")[1:]).upper()
comp = str.maketrans("ACGT","TGCA")
def revcomp(s): return s.translate(comp)[::-1]
stops = {"TAA","TAG","TGA"}
startc = {"ATG":20, "GTG":10, "TTG":5}  # weight ATG highest

def proper_orfs(s, minlen=60):
    res = []
    L = len(s)
    for strand_name, ss in [("+", s), ("-", revcomp(s))]:
        for frame in range(3):
            i = frame
            # find first stop in frame
            while i < L-2 and ss[i:i+3] not in stops:
                i += 3
            while i < L-2:
                stop = i+3
                # ORF = from last start codon before stop (upstream, in frame) with no stops after it
                st = None
                j = i-3
                while j >= frame:
                    if ss[j:j+3] in startc:
                        st = j
                        break
                    j -= 3
                if st is not None and (stop - st) >= minlen:
                    res.append((strand_name, st, stop, stop-st, ss[st:st+3]))
                # next stop
                i += 3
                while i < L-2 and ss[i:i+3] not in stops:
                    i += 3
    return res

res = sorted(proper_orfs(seq, 90), key=lambda x: -x[3])
for r in res[:15]:
    print(r)
