seq_txt = open("region.fasta").read()
seq = "".join(l.strip() for l in seq_txt.split("\n")[1:]).upper()
comp = str.maketrans("ACGT","TGCA")
def rc(s): return s.translate(comp)[::-1]

CS = {'TTT':'F','TTC':'F','TTA':'L','TTG':'L','TCT':'S','TCC':'S','TCA':'S','TCG':'S','TAT':'Y','TAC':'Y',
 'TAA':'*','TAG':'*','TGT':'C','TGC':'C','TGA':'*','TGG':'W','CTT':'L','CTC':'L','CTA':'L','CTG':'L',
 'CCT':'P','CCC':'P','CCA':'P','CCG':'P','CAT':'H','CAC':'H','CAA':'Q','CAG':'Q','CGT':'R','CGC':'R',
 'CGA':'R','CGG':'R','ATT':'I','ATC':'I','ATA':'I','ATG':'M','ACT':'T','ACC':'T','ACA':'T','ACG':'T',
 'AAT':'N','AAC':'N','AAA':'K','AAG':'K','AGT':'S','AGC':'S','AGA':'R','AGG':'R','GTT':'V','GTC':'V',
 'GTA':'V','GTG':'V','GCT':'A','GCC':'A','GCA':'A','GCG':'A','GAT':'D','GAC':'D','GAA':'E','GAG':'E',
 'GGT':'G','GGC':'G','GGA':'G','GGG':'G'}
def tr(s): return "".join(CS.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))

def orfs_correct(s, minlen=90):
    out = []
    L = len(s)
    for name, ss in [("+", s), ("-", rc(s))]:
        Ls = len(ss)
        for frame in range(3):
            last_start = None
            i = frame
            while i <= Ls-3:
                c = ss[i:i+3]
                if last_start is None and c in ("ATG","GTG","TTG"):
                    last_start = i
                if c in ("TAA","TAG","TGA"):
                    if last_start is not None and (i+3 - last_start) >= minlen:
                        out.append((name, last_start, i+3, i+3-last_start, ss[last_start:last_start+3]))
                    last_start = None
                i += 3
    return out

res = sorted([r for r in orfs_correct(seq) if r[3] >= 90], key=lambda r: (-r[3]))
print(f"{'strand':>6} {'fs1':>5} {'fs2':>5} {'len_nt':>7} {'aa':>4} start")
